js.cfg.mc:
#!bovnar 1.1
.spacecraft = {
    # Name im Badge „Orbit aktualisiert“
    .name = "NYX-1";
};

.orbit = {
    # Orbit-Epoche — natives datetime (daraus wird <datetime:64,unix> abgeleitet)
    .epoch           = 2026-05-28T00:00:00Z;
    # Erdradius + Bahnhöhe
    .altitude        = <float:64,k~m> 900.0;
    # Neigung der Bahnebene
    .inclination     = 100.0 deg;
    # Lage des aufsteigenden Knotens
    .raan            = 194.0 deg;
    # Startwinkel ab Knoten
    .arg_of_latitude = 0.0 deg;
};

.telemetry = {
    # Fehlerbehebung aktivieren
    .resync = true;
};

js.cfg.fin:
# ── ACME-Aktie — Konfiguration des Marktdaten-Feeds ────
# Kurse reisen als float_dec: exaktes Dezimalgeld, Währung inline.
.instrument = {
    .symbol       = "ACME";
    .currency     = USD;
    .decimals     = <uint:8> 2;
    .start_price  = <float_dec:64,$USD> 142.50;
    .volatility   = <float_dec:32,%> 1.1;       # Schwankung je Tick
    .spread       = <float_dec:64,$USD> 0.04;
    .fee_per_fill = <float_dec:64,$USD> 0.07;
};

.strategy = {
    .trade_size = <uint:32> 50;
    .max_pos    = <uint:32> 500;
};

.feed = {
    .resync = true;
};

js.cfg.ind:
# ── Reaktor R-204 — Konfiguration der SPS-Telemetrie ───
# Festkomma-Register tragen Skalierung (q) und Einheit inline.
.control = {
    .setpoint = <float_fix:16,q8,°C> 78.50;
    .kp       = <float_fix:16,q8>    3.0;
    .ki       = <float_fix:16,q8>    0.04;
    .kd       = <float_fix:16,q8>    6.0;
};

.limits = {
    .temp_max  = <float_fix:16,q8,°C>  86.0;
    .press_max = <float_fix:16,q8,bar> 3.0;
    .level_min = <float_fix:16,q8,%>   38.0;
};

.bus = {
    .resync = true;
};
